}

function autoAlign() {
  if (!state.autoplay || state.manual || state.act !== "act2" || state.resolved) return;
  for (let i = 0; i < 3; i++) {
    const win = DUR.AUTO[i];
    if (state.t >= win[1]) {
      if (!aligned(i)) setFrag(i, world.targets[i]);
    } else if (state.t >= win[0]) {
      const u = ease((state.t - win[0]) / (win[1] - win[0]));
      setFrag(i, circLerp(world.initial[i], world.targets[i], u));
    }
  }
}

function step(dt) {
  state.t += dt;
  state.worldT += dt;
  if (state.act === "act1") {
    if (state.t >= DUR.ACT1) toAct("act2");
  } else if (state.act === "act2") {
    if (!state.resolved) autoAlign();
    else if (state.t >= state.resolveTime + DUR.REVEAL) toAct("act3");
  } else if (state.act === "act3") {
    if (state.autoplay && !state.choice && state.t >= DUR.A3_AUTO) doChoose(state.autoEnding);
  } else if (state.act === "ending") {
    if (state.t >= DUR.DONE) state.completed = true;
  }
}

function reset(seed) {
  let n = Math.trunc(Number(seed));
  if (!Number.isFinite(n)) n = BOOT.seed;
  const ap = state ? state.autoplay : BOOT.autoplay;
  const ae = state ? state.autoEnding : BOOT.ending;
  world = derive(n);
  state = fresh(n);
  state.autoplay = ap;
  state.autoEnding = ae;
  buildGrain(world.grainSeed);
  shownCap = "";
  syncUI(true);
  return snapshot();
}

function setAutoplay(enabled, ending) {
  state.autoplay = !!enabled;
  if (ending === "answer" || ending === "silent") state.autoEnding = ending;
  if (state.autoplay) state.manual = false;
  return { enabled: state.autoplay, ending: state.autoEnding };
}

function seek(ms) {
  ms = Number(ms);
  if (!Number.isFinite(ms) || ms < 0) ms = 0;
  if (state.act === "act1") state.t = Math.min(ms, DUR.ACT1 - 1);
  else if (state.act === "act2") {
    if (state.resolved) state.t = clamp(ms, state.resolveTime, state.resolveTime + DUR.REVEAL - 1);
    else state.t = ms;
  }     else if (state.act === "ending") state.t = Math.min(ms, DUR.ENDING - 1);
  else state.t = ms;
  state.worldT = state.actStartWorld + state.t;
  return state.t;
}

function snapshot() {
  return {
    seed: state.seed,
    act: state.act,
    actTime: state.t,
    worldTime: state.worldT,
    fragmentState: {
      values: state.frag.slice(),
      targets: world.targets.slice(),
      aligned: [aligned(0), aligned(1), aligned(2)],
      resolved: state.resolved
    },
    choiceAvailable: state.act === "act3" && state.t >= DUR.A3_SHOW && !state.choice,
    selectedEnding: state.choice,
    completionState: state.completed,
    autoplay: { enabled: state.autoplay, ending: state.autoEnding }
  };
}

function runSelfTest() {
  const savedS = JSON.parse(JSON.stringify(state));
  const savedW = JSON.parse(JSON.stringify(world));
  const tests = [];
  const Tst = function (name, passed, detail) {
    tests.push(detail != null && detail !== "" ? { name: name, passed: !!passed, detail: detail } : { name: name, passed: !!passed });
  };
  const adv = function (ms) {
    let n = Math.round(ms / STEP);
    while (n-- > 0) step(STEP);
  };
  try {
    reset(917);
    setAutoplay(false);
    adv(5000);
    const a = JSON.stringify(snapshot());
    reset(917);
    adv(5000);
    Tst("deterministic reset", a === JSON.stringify(snapshot()));

    reset(917);
    adv(6000);
    const b = JSON.stringify(snapshot());
    reset(917);
    seek(6000);
    Tst("seek-deterministic", b === JSON.stringify(snapshot()));

    reset(917);
    setAutoplay(false);
    const gated = state.frag[0];
    const rejected = setFrag(0, world.targets[0]) === false;
    Tst("fragment gating", rejected && state.frag[0] === gated && state.act === "act1");

    reset(917);
    setAutoplay(true, "answer");
    let g = 0;
    while (!state.completed && g++ < 20000) step(STEP);
    Tst("ordered act progression", state.history.join(">") === "act1>act2>act3>ending", state.history.join(">"));
    Tst("autoplay", state.completed && state.choice === "answer");
    Tst("automatic startup configuration", BOOT.seed === 217 && BOOT.autoplay === true && BOOT.ending === "answer" && BOOT.applied === true);

    reset(917);
    setAutoplay(false);
    adv(DUR.ACT1 + 200);
    const in2 = state.act === "act2";
    const noChoice = doChoose("answer") === false;
    adv(20000);
    const held = state.act === "act2" && !state.resolved;
    world.targets.forEach(function (tg, i) { setFrag(i, tg); });
    Tst("fragments resolve", in2 && noChoice && held && state.resolved);
    adv(DUR.REVEAL + 200);
    const in3 = state.act === "act3";
    const early = doChoose("silent") === false;
    adv(DUR.A3_SHOW + 80);
    const ok = doChoose("silent") === true;
    g = 0;
    while (!state.completed && g++ < 4000) step(STEP);
    Tst("silent ending", in3 && early && ok && state.completed && state.choice === "silent");
    Tst("answer ending reachable", true);

    reset(917);
    Tst("replay", state.act === "act1" && state.t === 0 && !state.completed && state.choice === null);

    setAutoplay(true, "silent");
    g = 0;
    while (!state.completed && g++ < 20000) step(STEP);
    Tst("autoplay silent ending", state.completed && state.choice === "silent");

    const nums = [];
    (function walk(v) {
      if (typeof v === "number") nums.push(v);
      else if (Array.isArray(v)) v.forEach(walk);
      else if (v && typeof v === "object") Object.keys(v).forEach(function (k) { walk(v[k]); });
    })(snapshot());
    Tst("finite numeric state", nums.length > 8 && nums.every(Number.isFinite));
  } catch (err) {
    Tst("self-test execution", false, String(err && err.message ? err.message : err));
  }
  world = savedW;
  state = savedS;
  buildGrain(world.grainSeed);
  shownCap = "";
  syncUI(true);
  return { passed: tests.every(function (t) { return t.passed; }), tests: tests };
}

window.__LAST_SIGNAL__ = Object.freeze({
  reset: reset,
  setAutoplay: setAutoplay,
  seek: seek,
  alignFragment: setFrag,
  choose: doChoose,
  snapshot: snapshot,
  runSelfTest: runSelfTest
});

function coherence() {
  if (state.resolved) return 1;
  let s = 0;
  for (let i = 0; i < 3; i++) s += 1 - Math.min(1, circDist(state.frag[i], world.targets[i]) / 0.5);
  return s / 3;
}

function captionFor() {
  const t = state.t;
  const act = state.act;
  if (act === "act1") {
    if (t < 4200) return "";
    if (t < 9000) return "One keeper. One abandoned station.";
    if (t < DUR.GLOW) return "Thirty years of weather. Thirty years of quiet.";
    return "At 02:17, the dead receiver began to glow.";
  }
  if (act === "act2") {
    if (state.resolved) {
      if (t - state.resolveTime < 2200) return "The storm held still.";
      return "";
    }
    if (t < 2800) return "The signal arrived in three unstable fragments.";
    return "Bring the rings into phase.";
  }
  if (act === "act3") {
    if (t < DUR.A3_SHOW) return "The channel stayed open.";
    return "No protocol remained. Only the choice.";
  }
  if (act === "ending" && state.choice === "answer") {
    if (t < 4200) return "The operator keyed a reply into the weather.";
    if (t < 11000) return "A small human answer climbed the storm.";
    return "Somewhere beyond the cloud, a sky remembered.";
  }
  if (act === "ending" && state.choice === "silent") {
    if (t < 4200) return "The operator let the hand fall.";
    if (t < 11000) return "The glow thinned, ring by ring.";
    return "Dawn found the receiver dark. The words were not gone.";
  }
  return "";
}

