+    if (document.hidden) {
+      lastTick = now;
+      acc = 0;
+      return;
+    }
+    var delta = now - lastTick;
+    lastTick = now;
+    if (delta < 0) delta = 0;
+    if (delta > 100) delta = MAX_FRAME;
+    acc += delta;
+    var guard = 0;
+    while (acc >= STEP && guard++ < 6) {
+      step(STEP);
+      acc -= STEP;
+    }
+    sync();
+  }
+
+  var MAX_FRAME = 100;
+
+  window.__LAST_SIGNAL__ = Object.freeze({
+    reset: reset,
+    setAutoplay: setAutoplay,
+    seek: seek,
+    alignFragment: alignFragment,
+    choose: choose,
+    snapshot: snapshot,
+    runSelfTest: runSelfTest
+  });
+
+  reset(BOOT.seed);
+  setAutoplay(true, BOOT.ending);
+  BOOT.applied = true;
+  sync();
+  requestAnimationFrame(loop);
+})();
