function sync() {
  if (!state) return;
  resize();
  var cap = caption();
  if (cap !== shownLine) {
    lineEl.textContent = cap;
    shownLine = cap;
  }
  var hint = state.act === "act2" && !state.resolved;
  if (hint !== shownHint) {
    hintEl.hidden = !hint;
    shownHint = hint;
  }
  var msg = messageOn();
  if (msg !== shownMsg) {
    messageEl.hidden = !msg;
    shownMsg = msg;
  }
  render();
  if (msg && lastLayout) {
    var ring = ringPlacement(lastLayout);
    var anchor = worldToScreen(ring.x, ring.y - Math.min(48, ring.r * 0.28));
    messageEl.style.left = anchor.x + "px";
    messageEl.style.top = anchor.y + "px";
    var fade = 1;
    if (state.act === "ending" && state.choice === "silent") fade = clamp(1 - (state.t - 9000) / 6000, 0.15, 1);
    if (state.act === "ending" && state.choice === "answer") fade = clamp(1 - (state.t - 8000) / 6000, 0.2, 1);
    messageEl.style.opacity = String(fade);
  }
  var canChoose = choiceAvailable();
  if (canChoose !== shownChoices) {
    choicesEl.hidden = !canChoose;
    shownChoices = canChoose;
  }
  if (canChoose && !state.autoplay && !choiceArmed) {
    btnAnswer.focus();
    choiceArmed = true;
  }
  if (!canChoose) choiceArmed = false;
  barEl.style.width = (progress() * 100) + "%";
  document.body.classList.toggle("tuning", state.act === "act2" && !state.resolved);
  document.body.classList.toggle("done", !!state.completed);
  document.body.classList.toggle("choosing", canChoose);
}

