const page = await browser.getPage("last-signal");
const errors = [];
page.on("pageerror", (err) => errors.push("pageerror: " + err.message));
page.on("console", (msg) => { if (msg.type() === "error") errors.push("console: " + msg.text()); });
await page.setViewportSize({ width: 1440, height: 900 });
let clock = false;
try {
  await page.clock.install({ time: Date.now() });
  clock = true;
} catch (e) {
  console.log("clock", e.message);
}
await page.goto("file:///Users/melvynx/Developer/agent-benchmarks/benchmarks/the-last-signal/2026-09-21-cursor-agent-grok-4-7-high/index.html");
await page.waitForSelector("h1");
const title = await page.title();
const h1 = await page.locator("h1").textContent();
console.log(JSON.stringify({ title, h1, clock, errors }));

async function shot(name) {
  const buf = await page.screenshot({ type: "png" });
  const p = await saveScreenshot(buf, name);
  console.log("SHOT", name, p);
}
async function snap() {
  return await page.evaluate(() => {
    const s = window.__LAST_SIGNAL__.snapshot();
    return {
      act: s.act,
      actTime: Math.round(s.actTime),
      ending: s.selectedEnding,
      done: s.completionState,
      resolved: s.fragmentState.resolved,
      choice: s.choiceAvailable,
      line: document.getElementById("line").textContent,
      messageHidden: document.getElementById("message").hidden,
      message: document.getElementById("message").textContent,
      choicesHidden: document.getElementById("choices").hidden
    };
  });
}
async function advance(ms) {
  if (clock) await page.clock.runFor(ms);
  else await page.waitForTimeout(ms);
}

await page.evaluate(() => {
  window.__LAST_SIGNAL__.reset(217);
  window.__LAST_SIGNAL__.setAutoplay(false);
  window.__LAST_SIGNAL__.seek(1800);
});
await shot("01-open.png");
console.log("open", JSON.stringify(await snap()));

await page.evaluate(() => window.__LAST_SIGNAL__.seek(17500));
await shot("02-glow.png");
console.log("glow", JSON.stringify(await snap()));

await page.evaluate(() => {
