  font: 500 clamp(15px, 2.6vw, 30px)/1.25 "Iowan Old Style", Palatino, "Palatino Linotype", Georgia, serif;
  letter-spacing: 0.16em;
  text-shadow: 0 0 18px rgba(224, 138, 85, 0.35);
  transform: translate(-50%, -50%);
}
#choices {
  position: fixed;
  z-index: 4;
  left: 50%;
  bottom: max(36px, 5.5vh);
  transform: translateX(-50%);
  display: none;
  gap: 14px;
  width: min(560px, 92vw);
}
#choices:not([hidden]) { display: flex; }
#hint[hidden], #message[hidden] { display: none !important; }
button {
  font: 500 12px/1 "Iowan Old Style", Palatino, Georgia, serif;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--salt);
  background: rgba(8, 9, 13, 0.28);
  border: 1px solid rgba(224, 138, 85, 0.65);
  cursor: pointer;
}
#choices button {
  flex: 1;
  padding: 15px 12px;
}
#choices button:hover,
#choices button:focus-visible {
  background: rgba(224, 138, 85, 0.16);
}
#replay {
  position: fixed;
  z-index: 4;
  top: 14px;
  right: 18px;
  padding: 8px 2px;
  border: 0;
  background: transparent;
  color: rgba(230, 220, 203, 0.48);
  letter-spacing: 0.22em;
}
body.done #replay { color: rgba(230, 220, 203, 0.86); }
#replay:hover, #replay:focus-visible { color: var(--salt); }
:focus-visible {
  outline: 1px solid rgba(224, 138, 85, 0.95);
  outline-offset: 3px;
}
#progress {
  position: fixed;
  z-index: 5;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  background: rgba(230, 220, 203, 0.08);
