dev-browser <<'EOF'
const page = await browser.getPage("last-signal");
const errors = [];
page.on("pageerror", (err) => errors.push(err.message));
page.on("console", (msg) => { if (msg.type() === "error") errors.push(msg.text()); });
async function shot(name) {
  const buf = await page.screenshot({ type: "png" });
  const p = await saveScreenshot(buf, name);
  console.log("SHOT", name, p);
}
const before = await page.evaluate(() => window.__LAST_SIGNAL__.snapshot().fragmentState.values.slice());
await page.keyboard.press("1");
await page.keyboard.press("ArrowUp");
await page.keyboard.press("ArrowUp");
const afterKey = await page.evaluate(() => window.__LAST_SIGNAL__.snapshot().fragmentState.values.slice());
const box = await page.evaluate(() => {
  const c = document.getElementById("stage").getBoundingClientRect();
  return { w: c.width, h: c.height };
});
let hit = null;
for (let y = 180; y < 700; y += 36) {
  for (let x = 560; x < 1200; x += 40) {
    await page.mouse.click(x, y);
    const vals = await page.evaluate(() => window.__LAST_SIGNAL__.snapshot().fragmentState.values.slice());
    if (vals.some((v, i) => Math.abs(v - before[i]) > 0.02)) {
      hit = { x, y, vals };
      break;
    }
  }
  if (hit) break;
}
const resolved = await page.evaluate(() => {
  const api = window.__LAST_SIGNAL__;
  const s = api.snapshot();
  s.fragmentState.targets.forEach((t, i) => api.alignFragment(i, t));
  const n = api.snapshot();
  return { resolved: n.fragmentState.resolved, msg: document.getElementById("message").hidden === false, text: document.getElementById("message").textContent, act: n.act };
});
await shot("b-message.png");
console.log(JSON.stringify({ before, afterKey, hit, resolved, box, errors }, null, 0));
EOF

