  const s = window.__LAST_SIGNAL__.snapshot();
  return { title: document.title, h1: document.querySelector("h1").textContent, seed: s.seed, act: s.act, autoplay: s.autoplay, t: s.actTime };
});
await page.waitForTimeout(1200);
const moved = await page.evaluate(() => {
  const s = window.__LAST_SIGNAL__.snapshot();
  return { act: s.act, t: Math.round(s.actTime), choices: getComputedStyle(document.getElementById("choices")).display, msg: document.getElementById("message").hidden };
});
const test = await page.evaluate(() => window.__LAST_SIGNAL__.runSelfTest());
const restored = await page.evaluate(() => {
  const s = window.__LAST_SIGNAL__.snapshot();
  return { seed: s.seed, act: s.act, t: s.actTime, ending: s.autoplay, done: s.completionState };
});
await page.evaluate(() => { window.__LAST_SIGNAL__.reset(217); window.__LAST_SIGNAL__.setAutoplay(false); window.__LAST_SIGNAL__.seek(1600); });
const openBuf = await page.screenshot({ type: "png" });
console.log("SHOT open", await saveScreenshot(openBuf, "d-open.png"));
await page.click("#replay");
const replay = await page.evaluate(() => {
  const s = window.__LAST_SIGNAL__.snapshot();
  return { act: s.act, t: Math.round(s.actTime), seed: s.seed, autoplay: s.autoplay.enabled, done: s.completionState };
});
await page.setViewportSize({ width: 390, height: 844 });
await page.evaluate(() => { window.__LAST_SIGNAL__.reset(217); window.__LAST_SIGNAL__.setAutoplay(false); window.__LAST_SIGNAL__.seek(17000); });
const mobileBuf = await page.screenshot({ type: "png" });
console.log("SHOT mobile", await saveScreenshot(mobileBuf, "d-mobile.png"));
const fails = test.tests.filter((t) => !t.passed).map((t) => t.name + ":" + (t.detail || ""));
console.log(JSON.stringify({ boot, moved, passed: test.passed, fails, restored, replay, errors }, null, 2));
EOF

